"""Writes gate/testdata/compact_fixture.json: the golden output of the Python compact renderers
(mergeone.data.features.compact_state / compact_pair_state, PROTOCOL.md §R8 C1) on three run-3 PRs, which
the Go renderer (gate/internal/render) must reproduce byte for byte.

    PYTHONPATH=. python3 gate/testdata/gen_compact_fixture.py [path/to/data/run3/dataset.jsonl]

Run from the repository root. data/run3/dataset.jsonl is not committed (gitignored); the fixture is.
"""
import json
import sys
from pathlib import Path

from mergeone.data.features import compact_pair_state, compact_state
from mergeone.eval.run4 import _render_b, pair_state

# Row indices into data/run3/dataset.jsonl: 1 file / short diff / ASCII; 35 files / truncated diff / non-ASCII;
# 227 files / truncated diff (the "... and N more files" line is recomputed).
PICK = [1, 88, 103]
B_OF = {1: 103, 88: 1, 103: 88}  # the candidate B rendered beside each A

BODY = "\nMERGE MESSAGE BODY:\n"


def b_candidate(r):
    s = r["state"]
    title = s.split("\n", 1)[0][len("PULL REQUEST TITLE: "):]
    b0 = s.find(BODY) + len(BODY)
    body = s[b0: s.find("\n\nSUMMARY: ", b0)]
    f0 = s.find("\nFILES CHANGED (path +ins -del):\n") + len("\nFILES CHANGED (path +ins -del):\n")
    files = []
    for ln in s[f0: s.find("\nDIFF (first ", f0)].split("\n"):
        if ln.startswith("  ") and not ln.startswith("  ... and "):
            files.append(ln[2:].rsplit(" ", 2)[0])
    files = sorted(files)[:60]
    return {"title": title, "body": body, "state": "MERGED", "author": r["author"], "created_at": r["created_at"],
            "merged_at": r["merged_at"], "files": files}


def main():
    ds = Path(sys.argv[1] if len(sys.argv) > 1 else "data/run3/dataset.jsonl")
    rows = [json.loads(l) for l in ds.open()]
    cases = []
    for i in PICK:
        a = rows[i]["state"]
        b = b_candidate(rows[B_OF[i]])
        full_pair = pair_state(a, _render_b(b, b["body"], b["files"]))
        cases.append({"row": i, "pr_number": rows[i]["pr_number"], "a_state": a, "a_state_words": rows[i]["state_words"],
                      "b": b, "pair_state": full_pair,
                      "compact_state": compact_state(a), "compact_state_words": compact_state(rows[i]["state_words"]),
                      "compact_pair_state": compact_pair_state(full_pair, a)})
    out = {"source": "mergeone.data.features compact_state / compact_pair_state (run 8 §R8 C1 freeze) on data/run3/dataset.jsonl "
                     "rows " + ", ".join(map(str, PICK)) + "; generated by gate/testdata/gen_compact_fixture.py",
           "cases": cases}
    Path(__file__).with_name("compact_fixture.json").write_text(json.dumps(out, indent=1, ensure_ascii=False) + "\n")
    print("wrote", len(cases), "cases")


if __name__ == "__main__":
    main()
